#include "postquantiquecoin/blockchain/BlockUndo.h"
#include "postquantiquecoin/core/Serialization.h"
#include "postquantiquecoin/crypto/Hashing.h"
#include <algorithm>
namespace pqc { std::vector<uint8_t> BlockUndo::Serialize() const{ Serializer s; s.String("PQCUNDO"); s.String(blockHash); s.U64(height); s.U64(txUndos.size()); for(const auto& tu:txUndos){ s.U64(tu.spentOutputs.size()); for(const auto& u:tu.spentOutputs) s.Bytes(u.Serialize()); } auto body=s.Data(); auto chk=Hashing::Sha3_256(body); body.insert(body.end(),chk.begin(),chk.end()); return body;} Result<BlockUndo> BlockUndo::Deserialize(const std::vector<uint8_t>& data){ if(data.size()<32) return Result<BlockUndo>::Err("undo too small"); std::vector<uint8_t> body(data.begin(),data.end()-32); auto chk=Hashing::Sha3_256(body); if(!std::equal(chk.begin(),chk.end(),data.end()-32)) return Result<BlockUndo>::Err("undo checksum mismatch"); Deserializer d(body); BlockUndo u; auto m=d.String(); if(m.IsErr()||m.Value()!="PQCUNDO") return Result<BlockUndo>::Err("bad undo magic"); auto h=d.String(); if(h.IsErr()) return Result<BlockUndo>::Err(h.Error()); u.blockHash=h.Value(); auto ht=d.U64(); if(ht.IsErr()) return Result<BlockUndo>::Err(ht.Error()); u.height=ht.Value(); auto n=d.U64(); if(n.IsErr()) return Result<BlockUndo>::Err(n.Error()); for(uint64_t i=0;i<n.Value();++i){ TxUndo tu; auto c=d.U64(); if(c.IsErr()) return Result<BlockUndo>::Err(c.Error()); for(uint64_t j=0;j<c.Value();++j){ auto b=d.Bytes(); if(b.IsErr()) return Result<BlockUndo>::Err(b.Error()); auto ux=UTXO::Deserialize(b.Value()); if(ux.IsErr()) return Result<BlockUndo>::Err(ux.Error()); tu.spentOutputs.push_back(ux.Value()); } u.txUndos.push_back(tu);} std::copy(chk.begin(),chk.end(),u.checksum.begin()); return Result<BlockUndo>::Ok(u);} }
